<script setup>
import { ref,computed,onMounted,onBeforeUnmount,watch } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api'
import { storageKey,accountEpoch,setAccount } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
import ConfirmDialog from './ui/ConfirmDialog.vue'
const router=useRouter(),data=ref(null),answers=ref({}),version=ref(0),cursor=ref(0),error=ref(''),notice=ref(''),useAI=ref(false),ack=ref(false),uses=ref([]),preview=ref(null),neutral=ref(false),dirty=ref(false),writes=useWorkflowWrite('questionnaire'),epoch=accountEpoch,key=storageKey('questionnaire-daily-draft')
let ready=false,timer=null,alive=true
const questions=computed(()=>[...(data.value?.questions||[]),...(data.value?.draft?.followups||[]).flatMap(b=>b.questions)]),q=computed(()=>questions.value[cursor.value]),complete=computed(()=>questions.value.filter(q=>answers.value[q.id]?.state==='skipped'||answers.value[q.id]?.value?.trim()).length),history=computed(()=>data.value?.history?.at(-1)),futureLabels={judge:'事件与事实分析',review:'辅助回顾',report:'成长报告',pricing:'奖励定价'}
function persist(){if(ready)try{localStorage.setItem(key,JSON.stringify({answers:answers.value,cursor:cursor.value,uses:uses.value,version:version.value}))}catch{}}
function mark(){if(!ready||data.value?.onboarding_completed)return;dirty.value=true;persist();clearTimeout(timer);timer=setTimeout(save,900)}
watch(answers,mark,{deep:true,flush:'sync'});watch(uses,mark,{deep:true,flush:'sync'});watch(cursor,persist,{flush:'sync'})
async function load(){try{const result=await api.flow('/questionnaire');if(!alive||epoch!==accountEpoch)return;ready=false;data.value=result;version.value=result.draft?.version||0;preview.value=result.draft?.preview?.attributes?result.draft.preview:null;let cached=null;try{cached=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(cached?.version!==version.value)cached=null;answers.value=result.onboarding_completed?result.draft?.answers||{}:cached?.answers||result.draft?.answers||{};uses.value=cached?.uses||result.draft?.uses||[];cursor.value=cached?.cursor??questions.value.findIndex(q=>!answers.value[q.id]||answers.value[q.id].state==='answered'&&!answers.value[q.id].value.trim());if(cursor.value<0)cursor.value=questions.value.length;for(const q of questions.value)if(!answers.value[q.id])answers.value[q.id]={state:'answered',value:''};ready=true}catch(e){error.value=e.message}}
async function save(){if(!ready||writes.busy.value||data.value?.onboarding_completed)return;clearTimeout(timer);const snapshot=JSON.stringify(answers.value),groups=ack.value?[...new Set(questions.value.filter(q=>answers.value[q.id]?.state==='answered'&&answers.value[q.id]?.value.trim()).map(q=>q.group))]:[];try{const result=await writes.send('/questionnaire',{expected_version:version.value,answers:answers.value,send_groups:groups,uses:uses.value},'PUT');if(!alive||epoch!==accountEpoch)return;version.value=result.version;persist();data.value.draft=result;preview.value=null;dirty.value=snapshot!==JSON.stringify(answers.value);notice.value='答案已保存';error.value='';if(dirty.value)timer=setTimeout(save,900)}catch(e){error.value=e.message}}
async function next(skip=false){if(q.value&&skip)answers.value[q.value.id]={state:'skipped',value:''};await save();if(!error.value)cursor.value++}
async function skipRest(){for(const item of questions.value.slice(cursor.value))if(!answers.value[item.id]?.value.trim())answers.value[item.id]={state:'skipped',value:''};await save();if(!error.value)cursor.value=questions.value.length}
async function generate(final=false){await save();if(error.value||dirty.value||writes.busy.value)return;try{const result=await writes.send('/questionnaire/'+(final?'preview':'analyze'),{expected_version:version.value,use_ai:useAI.value,acknowledge_scope:ack.value});if(!alive||epoch!==accountEpoch)return;version.value=result.version;data.value.draft=result;preview.value=result.preview?.attributes?result.preview:null;for(const item of questions.value)if(!answers.value[item.id])answers.value[item.id]={state:'answered',value:''};if(result.stage==='followups')cursor.value=questions.value.findIndex(q=>!answers.value[q.id]?.value.trim()&&answers.value[q.id]?.state!=='skipped');else cursor.value=questions.value.length}catch(e){error.value=e.message;try{const current=await api.flow('/questionnaire');data.value.draft=current.draft;version.value=current.draft?.version||version.value}catch{}}}
async function confirm(){try{const result=await writes.send('/questionnaire/confirm',{expected_version:version.value});version.value=result.version;localStorage.removeItem(key);setAccount(await api.me());await load();notice.value='初始档案已建立，今后可以在长期信息里更新背景。'}catch(e){error.value=e.message}}
async function chooseNeutral(){if(writes.busy.value)return;writes.busy.value=true;try{await api.neutralBaseline();neutral.value=false;localStorage.removeItem(key);setAccount(await api.me());await router.push('/')}catch(e){error.value=e.message}finally{writes.busy.value=false}}
async function pause(){await save();if(!error.value&&!writes.busy.value)await router.push('/')}
async function permissions(){try{const result=await writes.send('/questionnaire/permissions',{expected_version:version.value,send_groups:data.value.draft.send_groups,uses:uses.value},'PUT');version.value=result.version;notice.value='后续用途授权已更新；问卷历史与属性保持不变。'}catch(e){error.value=e.message}}
onMounted(load);onBeforeUnmount(()=>{alive=false;clearTimeout(timer)})
</script>
<template><div class="reading-page questionnaire-page"><PageHeader :title="data?.onboarding_completed?'建档问卷记录':'先认识现在的你'" :description="data?.onboarding_completed?'保留当时的回答与评估，以后只更新新的背景。':'一题一屏，每题都可跳过；先保存基础回答，再整体分析。'"/><p v-if="error" class="error" role="alert">{{ error }} <RouterLink to="/settings">查看模型设置</RouterLink></p><p v-if="notice" role="status">{{ notice }}</p><button v-if="writes.pending.value&&data?.draft?.stage==='failed'" class="btn" :disabled="writes.busy.value" @click="writes.discardModelResult();error=''">结束失败的分析，保留答案继续填写</button><p v-if="data?.draft?.stage==='analyzing'" role="status">问卷分析仍在进行或结果待确认；请先读取当前状态。<button class="btn" @click="load">读取分析状态</button></p><template v-if="data?.onboarding_completed"><p v-if="data.history_incomplete" class="card">历史资料不完整；未保存的当时题目无法还原。<pre>{{ data.initial_snapshot }}</pre></p><section v-if="history" class="card"><h2>确认时的问卷</h2><article v-for="item in [...history.questions,...history.followups.flatMap(b=>b.questions)]" :key="item.id"><h3>{{ item.text }}</h3><p>{{ history.answers[item.id]?.state==='skipped'?'当时已跳过':history.answers[item.id]?.value||'当时未记录' }}</p></article><h2>初始评估</h2><p>{{ history.assessment.summary }}</p><p v-for="a in history.assessment.attributes" :key="a.name">{{ a.name }} {{ a.value }} · {{ a.reason }}</p><p>初始资金 {{ history.assessment.initial_coins }} 币</p></section><RouterLink class="btn" to="/personal-information">维护长期信息 →</RouterLink><details v-if="data.draft" class="card"><summary>调整后续 AI 用途授权</summary><label v-for="g in data.groups" :key="g.id"><input type="checkbox" v-model="data.draft.send_groups" :value="g.id"/>{{ g.title }}</label><label v-for="(label,id) in futureLabels" :key="id"><input type="checkbox" v-model="uses" :value="id"/>{{ label }}</label><button class="btn" :disabled="writes.busy.value" @click="permissions">保存用途授权</button></details></template><template v-else-if="data"><div class="wizard-progress" role="progressbar" :aria-valuenow="complete" :aria-valuemax="questions.length" aria-label="问卷进度"><span :style="{width:100*complete/Math.max(1,questions.length)+'%'}"/></div><p class="muted">已回答或跳过 {{ complete }} / {{ questions.length }} · {{ dirty?'本机草稿待保存':'可暂离恢复' }}</p><section v-if="q&&!preview" class="card wizard-card"><span class="eyebrow">{{ cursor<data.questions.length?'基础问题':'个性化补充' }} {{ cursor+1 }} / {{ questions.length }}</span><h2>{{ q.text }}</h2><textarea :disabled="writes.busy.value" v-model="answers[q.id].value" :aria-label="q.text" rows="5" maxlength="2000" @input="answers[q.id].state='answered'"/><p v-if="answers[q.id].state==='skipped'" class="muted">这题已跳过，也可以重新填写。</p><div class="action-group"><button class="btn" :disabled="cursor===0||writes.busy.value" @click="cursor--">上一题</button><button class="btn" :disabled="writes.busy.value" @click="next(true)">跳过这题</button><button class="btn primary" :disabled="writes.busy.value||!answers[q.id].value.trim()" @click="next()">保存并继续</button></div><button class="text-button" :disabled="writes.busy.value" @click="skipRest">其余问题先跳过</button></section><section v-else-if="!preview" class="card"><h2>基础回答已准备好</h2><p>先核对你愿意发送的范围，模型才会整体阅读；最多两轮，每轮三道个性化补题，也可直接收束。</p><label><input type="checkbox" v-model="useAI"/>使用本人模型整体分析</label><label v-if="useAI"><input type="checkbox" v-model="ack"/>允许本次发送已回答的内容（已跳过的问题不发送答案）</label><fieldset><legend>这些回答之后可用于（可全不选）</legend><label v-for="(label,id) in futureLabels" :key="id"><input type="checkbox" v-model="uses" :value="id"/>{{ label }}</label></fieldset><div class="action-group"><button class="btn" :disabled="writes.busy.value" @click="cursor=0">回看基础回答</button><button class="btn primary" :disabled="writes.busy.value||(useAI&&!ack)" @click="generate()">{{ writes.busy.value?'正在整体分析…':'整体分析并继续' }}</button><button v-if="data.draft?.followups?.length" class="btn" :disabled="writes.busy.value" @click="generate(true)">不再补题，生成预览</button></div></section><section v-if="preview" class="card"><h2>核对初始建议</h2><p>{{ preview.summary }}</p><div class="assessment-grid"><p v-for="a in preview.attributes" :key="a.name"><b>{{ a.name }} {{ a.value }}</b><span>{{ a.reason }}</span></p></div><p>启动资金：{{ preview.initial_coins }} 币</p><p v-if="preview.economic_reference">个人经济参考：{{ preview.economic_reference }}</p><button class="btn primary" :disabled="writes.busy.value" @click="confirm">核对并确认一次建档</button></section><div class="action-group"><button class="btn" :disabled="writes.busy.value" @click="pause">保存草稿，先去记录</button><button class="text-button" :disabled="writes.busy.value" @click="neutral=true">不评估，用游戏起点继续</button></div></template><ConfirmDialog :open="neutral" title="使用未评估的游戏起点" confirm-label="确认开始" :busy="writes.busy.value" @cancel="neutral=false" @confirm="chooseNeutral"><p>13维各50、80启动币属于游戏起点，不是能力评估。选择后初始评估不会重新覆盖。</p></ConfirmDialog></div></template>
